SELECT DISTINCT 'TRUE' FROM DUMMY where $[$38.U_suppprice.number] > IFNULL((Select (case when B."UomEntry"=X."UomEntry"  and X."UomEntry"=Y."BaseUom" then B."Price" when B."UomEntry"=X."UomEntry"  and X."UomEntry"<>Y."BaseUom" then B."Price"*1/X."AltQty"*X."BaseQty" when B."UomEntry"<>X."UomEntry" and X."UomEntry"<>Y."BaseUom" then B."Price"*1/X."AltQty"*X."BaseQty" when B."UomEntry"<>X."UomEntry" and X."UomEntry"=Y."BaseUom" then B."Price"else 0 end) from OITM C inner join (SELECT H."ItemCode",IFNULL((IFNULL(H."INMPrice", 0)/H."NumPerMsr"),0)-IFNULL((IFNULL(A1."INMPrice", 0)/A1."NumPerMsr"),0) as "Price", H."UomCode",H."UomEntry",H."NumPerMsr",Row_Number() over (partition by H."ItemCode" order by H."DocEntry" Desc) as "RN" FROM "PDN1" H left join OPDN A3 on A3."DocEntry"=H."DocEntry" left join ORPC A2 on  A2."U_GRPO"=A3."DocNum"left join RPC1 A1 on A2."DocEntry"=A1."DocEntry" and A1."ItemCode"=H."ItemCode" and A1."NoInvtryMv"='Y' where IFNULL(H."U_normalqty",0)<>0)B on C."ItemCode"=B."ItemCode" left join OUGP Y on Y."UgpEntry"=C."UgpEntry"  left JOIN UGP1 X ON Y."UgpEntry" = X."UgpEntry" where "RN"=1 and  B."ItemCode" = $[$38.1.0] and  X."UomEntry"=(Select "UomEntry" from OUOM where "UomCode"= $[$38.1470002145.0])),0)
